#include <bits/stdc++.h>
using namespace std;
int main(int c, char** v) { ifstream in(v[1]), out(v[2]), ans(v[3]); int n, m; in >> n >> m; vector<long long> a(n), b(n); for (auto& x : a) in >> x; for (auto& x : b) in >> x; vector<vector<bool>> can(n, vector<bool>(n, false)); for (int i = 0; i < n; i++) can[i][i] = true; for (int i = 0; i < m; i++) { int p, q; in >> p >> q; can[p - 1][q - 1] = can[q - 1][p - 1] = true; } string A, O; ans >> A; if (!(out >> O) || O != A) return 1; if (O == "NO") return 0; vector<long long> col(n, 0); for (int i = 0; i < n; i++) { long long row = 0; for (int j = 0; j < n; j++) { long long x; if (!(out >> x) || x < 0) return 1; if (x && !can[i][j]) return 1; row += x; col[j] += x; } if (row != a[i]) return 1; } for (int j = 0; j < n; j++) if (col[j] != b[j]) return 1; return 0; }
